using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public class CheckBatchTenGrip {
 public static void Run(){try{string root="D:/Projects/ChatGPT/7 days to delve";string basePath=File.ReadAllText(root+"/artifacts/batch-10/base.txt").Trim();var bundle=AssetBundle.LoadFromFile(basePath+"/Mods/ZDelvePresentation/Resources/forestweapons.unity3d");var report=new System.Text.StringBuilder();int count=0;
 foreach(string name in new[]{"delveStarterStaff","delveForgedStaff","delveStarterTotem","delveForgedTotem","delveMendingTotem","delveForgedMendingTotem","delveWardTotem"}){var native=new GameObject("NativeWandGrip");var v=UnityEngine.Object.Instantiate(bundle.LoadAsset<GameObject>(name),native.transform,false);var animator=v.GetComponent<Animator>();if(animator!=null)animator.enabled=false;v.transform.localRotation=Quaternion.Euler(90,0,0);var transforms=v.GetComponentsInChildren<Transform>(true);var weapon=transforms.First(t=>t.name=="Weapon");weapon.localPosition=Vector3.zero;weapon.localRotation=Quaternion.identity;var grip=transforms.First(t=>t.name=="GripRight");v.transform.localPosition-=native.transform.InverseTransformPoint(grip.position);var tip=transforms.First(t=>t.name=="EffectOriginSocket");if(grip.position.magnitude>.0001f)throw new Exception(name+" grip offset "+grip.position);if(tip.position.z<=.1f)throw new Exception(name+" does not point forward "+tip.position);report.AppendLine(name+" grip="+grip.position+" effect tip="+tip.position);count++;UnityEngine.Object.DestroyImmediate(native);}
 report.AppendLine("PASS "+count+" actual bundled staff/totem prefabs align their grip to the wand anchor and point forward.");File.WriteAllText(root+"/artifacts/batch-10/grip-validation.txt",report.ToString());EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);File.WriteAllText("../grip-failure.txt",e.ToString());EditorApplication.Exit(1);}}
}
